'use client';

import { ArrowUpRight, CalendarDays, CircleDollarSign, ClipboardPlus, UserPlus, Users, WalletCards } from 'lucide-react';
import Link from 'next/link';
import { format } from 'date-fns';
import { useActivity, useDashboard, useHeadcount, useTrend } from '@/lib/queries';
import { formatMoney } from '@/lib/api';
import { ActivityFeed } from './activity-feed';
import { AttendanceTrendChart, ChartCard, DepartmentChart } from './charts';
import { Button, Card, ErrorState, LinkButton, LoadingSkeleton, PageHeader, StatCard } from './ui';

export default function AdminDashboard() { const summary = useDashboard(); const trend = useTrend(); const headcount = useHeadcount(); const activity = useActivity(); if (summary.isLoading || trend.isLoading || headcount.isLoading) return <LoadingSkeleton rows={9} />; if (summary.isError) return <ErrorState message={summary.error.message} retry={() => summary.refetch()} />; return <div><PageHeader eyebrow="Admin workspace" title="Good morning, Mira." description="Here’s the clearest view of your people operations today." action={<LinkButton href="/admin/employees/new" variant="primary"><UserPlus className="h-4 w-4" />Add employee</LinkButton>} /><div className="mb-7 grid gap-4 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6"><StatCard label="Total employees" value={summary.data?.totalEmployees ?? 0} hint="Across all teams" icon={<Users className="h-5 w-5" />} accent="lavender" /><StatCard label="Active employees" value={summary.data?.activeEmployees ?? 0} hint="Currently working" icon={<UserPlus className="h-5 w-5" />} accent="lime" /><StatCard label="On leave" value={summary.data?.employeesOnLeave ?? 0} hint="Out today" icon={<CalendarDays className="h-5 w-5" />} accent="aqua" /><StatCard label="Attendance" value={`${summary.data?.attendancePercentage ?? 0}%`} hint="This month" icon={<ClipboardPlus className="h-5 w-5" />} accent="coral" /><StatCard label="Monthly payroll" value={formatMoney(summary.data?.monthlyPayrollTotal ?? 0)} hint="Current cycle" icon={<WalletCards className="h-5 w-5" />} accent="lavender" /><StatCard label="Pending payroll" value={formatMoney(summary.data?.pendingPayroll ?? 0)} hint="Needs review" icon={<CircleDollarSign className="h-5 w-5" />} accent="aqua" /></div><div className="grid gap-5 xl:grid-cols-[1.1fr_0.9fr]"><ChartCard title="Attendance trend" description="Rolling six-month team view"><AttendanceTrendChart data={trend.data ?? []} /></ChartCard><ChartCard title="Department headcount" description="People by department"><DepartmentChart data={headcount.data ?? []} /></ChartCard></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_0.72fr]"><ActivityFeed items={activity.data} /><Card className="p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.13em] text-[#ff725c]">Shortcuts</p><h2 className="mt-1 font-display text-xl">Quick actions</h2></div><ArrowUpRight className="h-5 w-5 text-[#a3a4a8]" /></div><div className="space-y-2"><QuickAction href="/admin/employees/new" icon={<UserPlus />} title="Add employee" description="Create a new people record" tone="coral" /><QuickAction href="/admin/attendance" icon={<CalendarDays />} title="Review attendance" description="Catch exceptions and corrections" tone="lime" /><QuickAction href="/admin/payroll" icon={<WalletCards />} title="Run payroll" description={`Review ${formatMoney(summary.data?.pendingPayroll ?? 0)} pending`} tone="lavender" /></div><div className="mt-5 rounded-2xl bg-[#fffaf1] p-4"><p className="text-xs font-semibold text-[#777982]">Workspace snapshot</p><p className="mt-2 text-sm font-bold">{format(new Date(), 'EEEE, d MMMM yyyy')}</p><p className="mt-1 text-xs text-[#85878d]">Everything is in sync with your latest data.</p></div></Card></div></div>; }
function QuickAction({ href, icon, title, description, tone }: { href: string; icon: React.ReactNode; title: string; description: string; tone: 'coral' | 'lime' | 'lavender' }) { return <Link href={href} className="flex items-center gap-3 rounded-xl border border-[#eeeae4] p-3 transition hover:border-[#ffb1a5] hover:bg-[#fffaf1]"><span className={`flex h-9 w-9 items-center justify-center rounded-xl [&>svg]:h-4 [&>svg]:w-4 ${tone === 'coral' ? 'bg-[#fff0ed] text-[#d95342]' : tone === 'lime' ? 'bg-[#eff9c7] text-[#658100]' : 'bg-[#eee9ff] text-[#7050b9]'}`}>{icon}</span><span className="min-w-0"><span className="block text-sm font-bold">{title}</span><span className="mt-0.5 block truncate text-xs text-[#85878d]">{description}</span></span><ArrowUpRight className="ml-auto h-4 w-4 text-[#a1a2a7]" /></Link>; }
